/** Validate that every fire fixture's ruleId matches one of the compiled battery's
 *  predicate IDs — the C26 closed-loop invariant. Call after both fixtures and
 *  battery are loaded. */
export function assertClosedLoop(fireFixtures: FireFixture[], battery: CompiledPredicate[]): void {
  const batteryIds = new Set(battery.map((p) => p.id));
  for (const f of fireFixtures) {
    if (!batteryIds.has(f.ruleId)) {
      throw new Error(
        `CLOSED_LOOP_VIOLATION: fire fixture ruleId '${f.ruleId}' has no matching predicate in the battery (ids: ${[...batteryIds].join(', ')})`
      );
    }
  }
}

