function stripComment(s: string): string {
  let q: string | null = null;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (q === null) {
      if (c === "'" || c === '"') q = c;
      else if (c === '#') return s.slice(0, i);
    } else if (q === "'") {
      if (c === "'") { if (s[i + 1] === "'") i++; else q = null; }
    } else {
      if (c === '\\') i++;
      else if (c === '"') q = null;
    }
  }
  return s;
}

